def transform(grid):
    g = np.array(grid)
    bg = background(g)
    body = 1
    mask = g != bg
    comps = components(mask, diagonal=False)
    pieces = []
    for c in comps:
        y0, x0, y1, x1 = bbox(c)
        cells = {(y - y0, x - x0): int(g[y, x]) for y, x in c}
        pieces.append({"cells": cells, "h": y1 - y0 + 1, "w": x1 - x0 + 1})
    # markers
    markers = {}
    for i, p in enumerate(pieces):
        for (y, x), v in p["cells"].items():
            if v != body:
                markers.setdefault(v, []).append((i, (y, x)))
    links = []
    for col, lst in markers.items():
        if len(lst) == 2 and lst[0][0] != lst[1][0]:
            links.append(lst)
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    def outside(p, y, x):
        return not (0 <= y < p["h"] and 0 <= x < p["w"])
    pos = {0: (0, 0)}
    occupied = {(y, x) for (y, x) in pieces[0]["cells"]}
    order = [0]
    changed = True
    while changed:
        changed = False
        for (ia, ma), (ib, mb) in links:
            for (a, m_a), (b, m_b) in (((ia, ma), (ib, mb)), ((ib, mb), (ia, ma))):
                if a in pos and b not in pos:
                    pa, pb = pieces[a], pieces[b]
                    for dy, dx in dirs:
                        if not outside(pa, m_a[0] + dy, m_a[1] + dx):
                            continue
                        if not outside(pb, m_b[0] - dy, m_b[1] - dx):
                            continue
                        ay, ax = pos[a]
                        gy, gx = ay + m_a[0] + dy, ax + m_a[1] + dx
                        oy, ox = gy - m_b[0], gx - m_b[1]
                        cells = {(oy + y, ox + x) for (y, x) in pb["cells"]}
                        if cells & occupied:
                            continue
                        pos[b] = (oy, ox)
                        occupied |= cells
                        order.append(b)
                        changed = True
                        break
    ys = [y for y, x in occupied]; xs = [x for y, x in occupied]
    miny, minx = min(ys), min(xs)
    H, W = max(ys) - miny + 1, max(xs) - minx + 1
    out = np.full((H, W), bg, dtype=int)
    emit(out, f"Allocate a {H}x{W} background canvas: the bounding box of all pieces joined at their matching markers.")
    for i in order:
        oy, ox = pos[i]
        for (y, x), v in pieces[i]["cells"].items():
            out[oy + y - miny, ox + x - minx] = v
        emit(out, f"Stamp piece {i} (unrotated) so its marker cells sit next to the matching markers of the pieces already placed.")
    emit(out, "Final assembly.")
    return out
